export const atomicMasses={H:1,C:12,O:16,Ca:40,Mg:24,S:32};
export function formulaMass(counts){return Object.entries(counts).reduce((n,[el,c])=>{if(!(el in atomicMasses)||!Number.isInteger(c)||c<0)throw new RangeError('Known elements and whole atom counts required');return n+atomicMasses[el]*c;},0);}
export const formulaTasks=[{formula:'H₂O',counts:{H:2,O:1},target:'O'},{formula:'CO₂',counts:{C:1,O:2},target:'C'},{formula:'Ca(OH)₂',counts:{Ca:1,O:2,H:2},target:'O'}];
export const repeatSets=[[2.38,2.40,2.42],[2.36,2.40,2.44],[3.1,3.2,3.3]];
export function statistics(values){if(!values.length||!values.every(Number.isFinite))throw new RangeError('Finite measurements required');const mean=values.reduce((a,b)=>a+b,0)/values.length,range=Math.max(...values)-Math.min(...values);return {mean,range,half:range/2};}
export const massTasks=[{name:'Oxygen entering',equation:'2Mg(s) + O₂(g) → 2MgO(s)',text:'2.4 g Mg combines with 1.6 g O₂. Predict the mass of MgO.',answer:4,reason:'enter',before:'2.4 g Mg + 1.6 g O₂',after:'4.0 g MgO'}, {name:'Gas leaving',equation:'CaCO₃(s) → CaO(s) + CO₂(g)',text:'10.0 g CaCO₃ produces 5.6 g CaO. Predict the mass of CO₂ leaving.',answer:4.4,reason:'leave',before:'10.0 g CaCO₃',after:'5.6 g CaO + 4.4 g CO₂'}, {name:'Whole system retained',equation:'CaCO₃(s) → CaO(s) + CO₂(g)',text:'The complete weighed system starts at 60.0 g. No material crosses its boundary. Predict its final total mass.',answer:60,reason:'closed',before:'60.0 g whole system',after:'60.0 g whole system'}];
export function magnesiumBalance(c){return c.length===3&&c.every(Number.isInteger)&&c[0]===c[2]&&2*c[1]===c[2]&&c.every(v=>v>0);}
